class SporadicTask:
    def __init__(self, C_i, D_i, T_i):
        self.C = C_i
        self.D = D_i
        self.T = T_i

class SporadicTaskSystem:
    def __init__(self, tasks_list):
        self.tasks = tasks_list
        self.n = len(tasks_list)

