def is_test_sustainable(test_F, policy_A, task_system_tau):
    # Assume test_F deems task_system_tau as A-schedulable

    # Iterate through all possible job collections J generated by tau
    for job_collection_J in task_system_tau.generate_all_job_collections():
        # Iterate through all possible 'better' job collections J_prime
        for job_collection_J_prime in generate_better_behavior_collections(job_collection_J):
            if not policy_A.schedules_all_deadlines(job_collection_J_prime):
                return False # Policy A failed for a 'better' scenario, so test F's guarantee was not sustainable
    return True # Test F is sustainable

# generate_better_behavior_collections is the same as in Definition 1

# Assuming calculate_DBF function is available

def calculate_system_DBF(task_system_tau, interval_t):
    total_demand = 0
    for task_i in task_system_tau.tasks:
        total_demand += calculate_DBF(task_i, interval_t)
    return total_demand

def calculate_LOAD(task_system_tau, max_t_to_check=10000): # max_t_to_check for practical approximation
    max_load = 0.0
    # In practice, t only needs to be checked at specific points (e.g., deadlines)
    # For a formal definition, it's max over all t > 0
    for t in range(1, max_t_to_check + 1): 
        if t > 0:
            current_load = calculate_system_DBF(task_system_tau, t) / t
            if current_load > max_load:
                max_load = current_load
    return max_load

def calculate_delta_max(task_system_tau):
    max_density = 0.0
    for task_i in task_system_tau.tasks:
        task_density = task_i.C / min(task_i.D, task_i.T)
        if task_density > max_density:
            max_density = task_density
    return max_density

