def is_system_global_EDF_schedulable_test_6(task_system_tau, num_processors_m):
    for task_k in task_system_tau.tasks:
        D_k = task_k.D
        C_k = task_k.C

        max_allowable_interference_k = D_k - C_k
        total_slack_m = num_processors_m * max_allowable_interference_k

        sum_interference = 0
        condition_6_met = False # Tracks if there's any i!=k with I_i_k <= (D_k - C_k)

        for task_i in task_system_tau.tasks:
            if task_i != task_k:
                I_i_k_val = calculate_I_i_k(task_i.C, task_i.D, task_i.T, D_k)
                sum_interference += min(max_allowable_interference_k, I_i_k_val)

                if I_i_k_val <= max_allowable_interference_k:
                    condition_6_met = True

        # Check condition 5
        if sum_interference < total_slack_m:
            continue # task_k is schedulable
        # If condition 5 is not met, check condition 6
        elif sum_interference == total_slack_m and condition_6_met:
            continue # task_k is schedulable
        else:
            return False # task_k is not schedulable by this test

    return True # All tasks are schedulable
